// Convert HTML to Slack mrkdwn
const html = $('AI Draft Customer Reply').first().json.output.email_body;

const slackBody = html
  // Convert links
  .replace(/<a\s+href=["']([^"']+)["'][^>]*>([^<]+)<\/a>/gi, '<$1|$2>')
  // Convert bold
  .replace(/<(strong|b)>([^<]+)<\/(strong|b)>/gi, '*$2*')
  // Convert italic
  .replace(/<(em|i)>([^<]+)<\/(em|i)>/gi, '_$2_')
  // Convert ordered lists - number each item
  .replace(/<ol[^>]*>([\s\S]*?)<\/ol>/gi, (match, content) => {
    let counter = 0;
    return content.replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, (m, text) => {
      counter++;
      return `${counter}. ${text.trim()}\n`;
    });
  })
  // Convert unordered lists - bullet each item
  .replace(/<ul[^>]*>([\s\S]*?)<\/ul>/gi, (match, content) => {
    return content.replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, '• $1\n');
  })
  // Catch any remaining standalone <li> tags
  .replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, '• $1\n')
  // Horizontal rules
  .replace(/<hr\s*\/?>/gi, '\n---\n')
  // Paragraphs
  .replace(/<p>/gi, '')
  .replace(/<\/p>/gi, '\n\n')
  // Line breaks
  .replace(/<br\s*\/?>/gi, '\n')
  // Clean up extra newlines
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{ json: { email_body: slackBody } }];

// Build the auto-acknowledgement email as a base64url encoded RFC822 message.
const settings = $('Set Support Parameters').first().json;
const companyName = settings.companyName;
const fromAddress = settings.supportFromEmail;
const sla = settings.responseTimeSla || '24 hours';

const parseEmail = $('Parse Email Content').first().json;
const recipient = parseEmail.email;
const firstName = parseEmail.firstName || parseEmail.name?.split(' ')[0] || 'Valued Customer';

const subject = "Confirmation: Request Received";

const body = `
<p>Hello ${firstName},</p>

<p>Thank you for contacting ${companyName}! Our team has received your request, and we'll get back to you within <strong>${sla}</strong>.</p>

<p>Best regards,<br>
${companyName} Team</p>
`;

const email = [
  `From: ${companyName} <${fromAddress}>`,
  `To: ${recipient}`,
  "Subject: " + subject,
  "Content-Type: text/html; charset=UTF-8",
  "",
  body
].join("\n");

const encodedEmail = Buffer.from(email)
  .toString("base64")
  .replace(/\+/g, "-")
  .replace(/\//g, "_")
  .replace(/=+$/, "");

return [{ json: { raw: encodedEmail } }];

