// Get thread ID directly from Gmail response (not from headers)
const threadId = $json.threadId;
const messageId = $json.id;

// Also get Message-ID header if you still need it
const headers = $json.payload?.headers || [];
const messageIdHeader = headers.find(h => h.name === 'Message-ID');
const emailMessageId = messageIdHeader ? messageIdHeader.value : null;

return [{ 
  json: { 
    threadId,      // Gmail thread ID (use this for Thread → Get)
    messageId,     // Gmail message ID
    emailMessageId // Email header Message-ID (for References header)
  } 
}];

// Code node (JavaScript) — Run Once for All Items
// Reads fields from "Edit Fields" safely and adds "Re: " if not present.

const editItem = ($items("Extract Key Email Details")[0]?.json) ?? {};
const fromRaw = String(editItem.From ?? "").trim();

// --- Parse name + email ---
let name = null;
let email = null;

const angleMatch = fromRaw.match(/^\s*(?:"?([^"<]+?)"?\s*)?<\s*([^>]+)\s*>\s*$/); // Name <email>
if (angleMatch) {
  name  = angleMatch[1]?.trim() || null;
  email = angleMatch[2].trim();
} else {
  const emailMatch = fromRaw.match(/([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
  if (emailMatch) {
    email = emailMatch[1].trim();
    const before = fromRaw.slice(0, fromRaw.indexOf(email))
                          .replace(/[<>"()]/g, "")
                          .trim();
    name = before || null;
  }
}

let firstName = name ? name.split(/\s+/)[0] : null;
const formatted = email ? (name ? `${name} <${email}>` : `<${email}>`) : "";

// --- Subject logic with "Re:" ---
let subject = editItem.Subject ?? "";
if (subject && !/^Re:/i.test(subject)) {
  subject = `Re: ${subject.trim()}`;
}

// --- Pass through other fields ---
const threadId = editItem.threadId ?? null;
const id       = editItem.id ?? null;

// --- Output single item ---
return [{
  json: {
    fromRaw,
    name,
    firstName,
    email,
    formatted,
    Subject: subject,   // now automatically prefixed with "Re:" if needed
    threadId,
    id
  }
}];

// Build a readable thread transcript and count prior exchanges.
// Support-side messages are identified from the address list in the Settings node.
const settings = $('Set Support Parameters').first().json;
const supportAddresses = String(settings.supportEmailAddresses || '')
  .split(',')
  .map(s => s.trim().toLowerCase())
  .filter(Boolean);

const messages = $input.all();
const currentMessageId = $('Extract Key Email Details').item.json.id;

const history = messages
  .filter(msg => msg.json.id !== currentMessageId)
  .sort((a, b) => parseInt(a.json.internalDate || 0) - parseInt(b.json.internalDate || 0))
  .map(msg => {
    const from = String(msg.json.From || '').toLowerCase();
    const date = new Date(parseInt(msg.json.internalDate || 0)).toLocaleString();
    const snippet = msg.json.snippet || '';
    const isSupport = supportAddresses.some(addr => from.includes(addr));
    return '[' + (isSupport ? 'SUPPORT' : 'CUSTOMER') + ' - ' + date + ']:\n' + snippet;
  });

const threadHistory = history.length > 0
  ? '## Previous Messages\n\n' + history.join('\n\n---\n\n')
  : 'No previous messages in thread.';

return [{ json: { threadHistory: threadHistory, messageCount: history.length } }];
